function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 10000) return 's needs 1 to 10,000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's contains only lowercase English letters.';
  if (!Number.isInteger(k) || k < 1 || k > 100000) return 'k is between 1 and 10^5.';
  return null;
}

