function longestSubstring(s, k) {
  return solve(0, s.length);

  function solve(start, end) {
    if (end - start < k) {
      return 0;
    }
    const counts = new Array(26).fill(0);
    for (let i = start; i < end; i++) {
      counts[s.charCodeAt(i) - 97]++;
    }
    let best = 0;
    let left = start;
    let split = false;
    for (let right = start; right < end; right++) {
      if (counts[s.charCodeAt(right) - 97] < k) {
        best = Math.max(best, solve(left, right));
        left = right + 1;
        split = true;
      }
    }
    if (!split) {
      return end - start;
    }
    return Math.max(best, solve(left, end));
  }
}

