function longestSubstring(s, k) {
  let answer = 0;
  for (let i = 0; i < s.length; i++) {
    const freq = new Map();
    let distinct = 0, enough = 0;
    for (let j = i; j < s.length; j++) {
      const c = s[j];
      const times = (freq.get(c) || 0) + 1;
      freq.set(c, times);
      if (times === 1) distinct++;
      if (times === k) enough++;
      if (distinct === enough) answer = Math.max(answer, j - i + 1);
    }
  }
  return answer;
}

