function generate(rand, size) {
  if (size === 'large') {
    const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, 3 + Math.floor(rand() * 24));
    let s = '';
    while (s.length < 10000) s += letters[Math.floor(rand() * letters.length)].repeat(1 + Math.floor(rand() * 8));
    return [s.slice(0, 10000), 1 + Math.floor(rand() * 400)];
  }
  const n = 1 + Math.floor(rand() * 14);
  const letters = 'abcd'.slice(0, 1 + Math.floor(rand() * 4));
  let s = '';
  while (s.length < n) s += letters[Math.floor(rand() * letters.length)].repeat(1 + Math.floor(rand() * 3));
  const k = rand() < 0.1 ? 100000 : 1 + Math.floor(rand() * 4);
  return [s.slice(0, n), k];
}
